import itertools, random, sys, math, time

def has_cycle_of_length_at_most(edges, n, max_len):
    """Check if graph has any cycle of length <= max_len"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS/DFS to find cycles up to max_len
    # Use DFS with parent tracking
    visited = [False]*n
    parent = [-1]*n
    depth = [0]*n

    def dfs(u, p, d):
        visited[u] = True
        parent[u] = p
        depth[u] = d
        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # cycle found
                cycle_len = d - depth[v] + 1
                if cycle_len <= max_len:
                    return True
            else:
                if dfs(v, u, d+1):
                    return True
        return False

    for u in range(n):
        if not visited[u]:
            if dfs(u, -1, 0):
                return True
    return False

def girth_at_least(edges, n, g):
    """Check if girth >= g (no cycles of length < g)"""
    return not has_cycle_of_length_at_most(edges, n, g-1)

def is_3_colorable(edges, n):
    """Check if graph is 3-colorable using backtracking"""
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1]*n

    def backtrack(v):
        if v == n:
            return True
        # Try colors 0,1,2
        used = set()
        for nb in adj[v]:
            if colors[nb] != -1:
                used.add(colors[nb])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

