def find_all_cycles_up_to(edges, n, max_len):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)

    cycles = []

    def dfs(path, visited_set):
        u = path[-1]
        for v in adj[u]:
            if v == path[0] and len(path) >= 3 and len(path) <= max_len:
                cycles.append(path.copy())
            elif v not in visited_set and len(path) < max_len:
                visited_set.add(v)
                path.append(v)
                dfs(path, visited_set)
                path.pop()
                visited_set.remove(v)

    for start in range(n):
        dfs([start], {start})

    return cycles

